/**
 * Company domain from a PTR record (SPEC §5.2 step 6, after ipapi.is `company.domain`; no
 * RDAP). Only hostnames that look like a company's own server count: names generated by an
 * ISP for a customer line (static-1-2-3-4, dsl, cable, pool, dhcp, …) say nothing about who
 * uses the address.
 */
import { Resolver } from 'node:dns/promises';

export type PtrLookup = (ip: string) => Promise<string[]>;

export function systemPtr(timeoutMs = 2000): PtrLookup {
  const resolver = new Resolver({ timeout: timeoutMs, tries: 1 });
  return async (ip) => {
    try {
      return await resolver.reverse(ip);
    } catch {
      return [];
    }
  };
}

/** Second-level labels under which the registrable domain has three labels. */
const SECOND_LEVEL = new Set(['co', 'com', 'net', 'org', 'gov', 'edu', 'ac', 'k12', 'ltd', 'plc']);

const GENERATED =
  /(^|[.-])(static|dynamic|dyn|dhcp|dsl|adsl|vdsl|cable|cpe|pool|ppp|pppoe|res|resi|residential|cust|customer|client|host|ip|broadband|fiber|fios|ftth|wireless|mobile|lte|nat|unassigned|rev|reverse|in-addr|ip6|ipv6)([.-]|\d|$)/i;

/** Hosting, cloud and ISP domains whose PTR names never identify the visitor's company. */
const NETWORK_DOMAINS = new Set([
  'amazonaws.com',
  'googleusercontent.com',
  '1e100.net',
  'cloudfront.net',
  'akamaitechnologies.com',
  'linodeusercontent.com',
  'vultrusercontent.com',
  'your-server.de',
  'contaboserver.net',
  'comcast.net',
  'comcastbusiness.net',
  'verizon.net',
  'att.net',
  'sbcglobal.net',
  'rr.com',
  'charter.com',
  'spectrum.com',
  'cox.net',
  'coxbusiness.net',
  'frontiernet.net',
  'centurylink.net',
  'qwest.net',
  'lumen.com',
  'level3.net',
  'cogentco.com',
  'zayo.com',
  'windstream.net',
  'optonline.net',
  'myvzw.com',
  'tmodns.net',
  'mycingular.net',
  'starlinkisp.net',
  'hughes.net',
]);

export function registrableDomain(host: string): string | null {
  const labels = host.toLowerCase().replace(/\.$/, '').split('.').filter(Boolean);
  if (labels.length < 2) return null;
  const n =
    labels[labels.length - 2]!.length <= 3 &&
    SECOND_LEVEL.has(labels[labels.length - 2]!) &&
    labels.length >= 3
      ? 3
      : 2;
  return labels.slice(-n).join('.');
}

/** The company domain a PTR hostname points to, or null when it looks ISP-generated. */
export function domainFromPtr(host: string, ip: string): string | null {
  const h = host.toLowerCase().replace(/\.$/, '');
  if (GENERATED.test(h)) return null;
  // Hostnames that embed the address (1-2-3-4, 1.2.3.4, 010002003004) are ISP-generated.
  const octets = ip.split('.');
  if (
    octets.length === 4 &&
    (h.includes(octets.join('-')) || h.includes([...octets].reverse().join('-')) || h.includes(ip))
  )
    return null;
  const domain = registrableDomain(h);
  if (!domain || NETWORK_DOMAINS.has(domain)) return null;
  return domain;
}
